        let resourcesPerClick = getResourcesPerClick()() * getTicksPerSecond()(), haveTech = getHaveTech(), conjureMod = haveTech("conjuring", 2) ? 10 : 1;
        buildings.Food.isClickable() && !game.global.race.fasting && (resources.Food.rateOfChange += resourcesPerClick * settings.buildingClickPerTick * conjureMod), buildings.Lumber.isClickable() && (resources.Lumber.rateOfChange += resourcesPerClick * settings.buildingClickPerTick * conjureMod), buildings.Stone.isClickable() && (resources.Stone.rateOfChange += resourcesPerClick * settings.buildingClickPerTick * conjureMod), buildings.Chrysotile.isClickable() && (resources.Chrysotile.rateOfChange += resourcesPerClick * settings.buildingClickPerTick * conjureMod), buildings.Slaughter.isClickable() && (resources.Lumber.rateOfChange += resourcesPerClick * settings.buildingClickPerTick, game.global.race.soul_eater && haveTech("primitive", 2) && (resources.Food.rateOfChange += resourcesPerClick * settings.buildingClickPerTick), resources.Furs.isUnlocked() && (resources.Furs.rateOfChange += resourcesPerClick * settings.buildingClickPerTick));
